import openpyxl
from openpyxl.styles import PatternFill

wb = openpyxl.load_workbook('init.xlsx')
ds = wb['Datensatz']
an = wb['Analyse']

data = {}
for r in range(4, 34):
    for c in range(4, 12):
        data[(r, c)] = ds.cell(row=r, column=c).value or 0

N = 30

def count_both(p1, p2):
    cnt = 0
    for r in range(4, 34):
        if data[(r, 3+p1)] > 0 and data[(r, 3+p2)] > 0:
            cnt += 1
    return cnt

fill = PatternFill(start_color="F2F2F2", end_color="F2F2F2", fill_type="solid")

for row_prod in range(1, 9):
    for col_prod in range(1, 9):
        cell = an.cell(row=4+row_prod, column=3+col_prod)
        cell.fill = fill
        if row_prod == col_prod:
            val = 1
        else:
            val = count_both(row_prod, col_prod) / N
        cell.number_format = '0.##########'  # up to 10 decimals, trailing zeros omitted
        cell.value = val

wb.save('output.xlsx')
print("done")
EOF
python3 solve.py
